import { IHikingScheduleResult } from '@apps/Hiking/@types/hikingScheduleResults.types';
import { showModal } from '@ui-kit/Modal';

import ScheduleResultEditModal, { IScheduleEditModalProps } from './index';
interface IShowScheduleEditModalArgs extends IScheduleEditModalProps {
  title?: string;
}

export const showScheduleResultEditModal = ({
  scheduleResult,
  onSave,
  title,
}: IShowScheduleEditModalArgs) => {
  showModal({
    title: title || scheduleResult?.id ? 'Редактирование результата' : 'Добавление результата]',
    children: (close: () => void) => (
      <ScheduleResultEditModal
        scheduleResult={scheduleResult}
        onSave={(up) => {
          close();
          onSave?.(up);
        }}
      />
    ),
  });
};
export const showScheduleResultEditModalAsync = ({
  scheduleResult,
  title,
}: Omit<IShowScheduleEditModalArgs, 'onSave'>): Promise<IHikingScheduleResult> => {
  return new Promise((res) => {
    showModal({
      title: title || scheduleResult?.id ? 'Редактирование результата' : 'Добавление результата',
      children: (close: () => void) => (
        <ScheduleResultEditModal
          scheduleResult={scheduleResult}
          onSave={(up) => {
            close();
            res(up);
          }}
        />
      ),
    });
  });
};
